</main>

<script>
(function () {
	'use strict';

	var page = document.getElementById('ces-2027-page');
	var nav = document.getElementById('ces-section-nav');
	if (!page) {
		return;
	}

	var toggle = nav ? nav.querySelector('.ces-nav-toggle') : null;
	var links = nav ? nav.querySelectorAll('.ces-nav-links a') : [];
	var sections = page.querySelectorAll('.ces-section, .ces-contact');

	if (toggle && nav) {
		toggle.addEventListener('click', function () {
			var isOpen = nav.classList.toggle('is-open');
			toggle.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
		});
	}

	links.forEach(function (link) {
		link.addEventListener('click', function () {
			if (nav) {
				nav.classList.remove('is-open');
			}
			if (toggle) {
				toggle.setAttribute('aria-expanded', 'false');
			}
		});
	});

	function measureThemeHeaderOffset() {
		var admin = document.getElementById('wpadminbar');
		var adminHeight = admin ? (admin.offsetHeight || 0) : 0;
		var isMobileView = window.matchMedia('(max-width: 782px)').matches;
		var mobileBuffer = isMobileView ? 6 : 0;

		function visibleHeight(el) {
			if (!el) {
				return 0;
			}
			var style = window.getComputedStyle(el);
			if (style.display === 'none' || style.visibility === 'hidden') {
				return 0;
			}
			var rect = el.getBoundingClientRect();
			return Math.max(rect.height, el.offsetHeight || 0, el.scrollHeight || 0);
		}

		if (isMobileView) {
			var mobileRoot = document.querySelector('#qodef-page-mobile-header') || document.querySelector('.qodef-mobile-header-wrapper');
			if (mobileRoot) {
				var mobileRect = mobileRoot.getBoundingClientRect();
				var pageTop = page.getBoundingClientRect().top;
				var overlap = mobileRect.bottom - pageTop;
				if (overlap <= 1) {
					return 0;
				}
				return Math.round(overlap + mobileBuffer);
			}
		}

		var selectors = [
			'#wpadminbar',
			'#qodef-page-mobile-header',
			'.qodef-mobile-header-wrapper',
			'#qodef-page-header',
			'.qodef-header-sticky',
			'header.site-header',
			'#masthead'
		];
		var seen = typeof WeakSet !== 'undefined' ? new WeakSet() : null;
		var maxBottom = 0;

		selectors.forEach(function (selector) {
			document.querySelectorAll(selector).forEach(function (el) {
				if (seen && seen.has(el)) {
					return;
				}
				if (seen) {
					seen.add(el);
				}
				var style = window.getComputedStyle(el);
				if (style.display === 'none' || style.visibility === 'hidden') {
					return;
				}
				var rect = el.getBoundingClientRect();
				if (rect.height < 1) {
					return;
				}
				var pinned = style.position === 'fixed' || style.position === 'sticky';
				if (!pinned && rect.top > 6) {
					return;
				}
				if (isMobileView && selector === '#qodef-page-header' && document.querySelector('#qodef-page-mobile-header')) {
					return;
				}
				maxBottom = Math.max(maxBottom, rect.bottom, adminHeight + visibleHeight(el));
			});
		});

		if (maxBottom < 1) {
			maxBottom = isMobileView ? 92 : 88;
		}

		return Math.round(maxBottom + mobileBuffer);
	}

	function updateNavOffsets() {
		var navHeight = nav ? nav.offsetHeight : 72;
		var stickyTop = measureThemeHeaderOffset();
		var offsetValue = stickyTop + 'px';

		document.body.style.setProperty('--ces-theme-header-offset', offsetValue);
		page.style.setProperty('--ces-theme-header-offset', offsetValue);
		page.style.setProperty('--ces-sticky-top', offsetValue);
		page.style.setProperty('--ces-scroll-offset', (stickyTop + navHeight + 24) + 'px');

		if (nav) {
			nav.classList.remove('ces-nav-mobile-static');
		}
	}

	function syncOffsetsSoon() {
		updateNavOffsets();
		window.requestAnimationFrame(function () {
			updateNavOffsets();
			window.requestAnimationFrame(updateNavOffsets);
		});
	}

	syncOffsetsSoon();
	window.addEventListener('DOMContentLoaded', syncOffsetsSoon);
	window.addEventListener('resize', syncOffsetsSoon);
	window.addEventListener('load', syncOffsetsSoon);
	window.addEventListener('orientationchange', syncOffsetsSoon);

	if (typeof ResizeObserver !== 'undefined') {
		var headerResizeObserver = new ResizeObserver(function () {
			updateNavOffsets();
		});
		['#wpadminbar', '#qodef-page-mobile-header', '.qodef-mobile-header-wrapper', '#qodef-page-header'].forEach(function (selector) {
			document.querySelectorAll(selector).forEach(function (el) {
				headerResizeObserver.observe(el);
			});
		});
	}

	window.addEventListener('scroll', function () {
		updateNavOffsets();
		if (!nav) {
			return;
		}
		nav.classList.toggle('is-scrolled', window.scrollY > 12);
	}, { passive: true });

	if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
		var revealItems = page.querySelectorAll('.ces-reveal');
		if ('IntersectionObserver' in window) {
			var revealObserver = new IntersectionObserver(function (entries) {
				entries.forEach(function (entry) {
					if (entry.isIntersecting) {
						entry.target.classList.add('is-visible');
						revealObserver.unobserve(entry.target);
					}
				});
			}, { threshold: 0.15, rootMargin: '0px 0px -8% 0px' });

			revealItems.forEach(function (el) {
				if (!el.classList.contains('is-visible')) {
					revealObserver.observe(el);
				}
			});

			var sectionObserver = new IntersectionObserver(function (entries) {
				entries.forEach(function (entry) {
					entry.target.classList.toggle('ces-in-view', entry.isIntersecting);
				});
			}, { threshold: 0.2 });

			page.querySelectorAll('.ces-section').forEach(function (section) {
				sectionObserver.observe(section);
			});
		} else {
			revealItems.forEach(function (el) {
				el.classList.add('is-visible');
			});
		}
	} else {
		page.querySelectorAll('.ces-reveal').forEach(function (el) {
			el.classList.add('is-visible');
		});
	}


	var film = document.getElementById('pavilion-film');
	var motionControl = document.getElementById('motion-control');
	if (film && motionControl) {
		var motionPreference = window.matchMedia('(prefers-reduced-motion: reduce)');
		function playFilm() {
			film.play().catch(function () {});
		}
		film.addEventListener('play', function () {
			motionControl.textContent = 'Pause animation';
		});
		film.addEventListener('pause', function () {
			motionControl.textContent = 'Play animation';
		});
		motionControl.addEventListener('click', function () {
			if (film.paused) {
				playFilm();
			} else {
				film.pause();
			}
		});
		motionControl.hidden = false;
		if (!motionPreference.matches) {
			playFilm();
		}
		motionPreference.addEventListener('change', function () {
			if (motionPreference.matches) {
				film.pause();
			} else {
				playFilm();
			}
		});
	}

	if ('IntersectionObserver' in window && links.length) {
		var navObserver = new IntersectionObserver(function (entries) {
			entries.forEach(function (entry) {
				if (!entry.isIntersecting) {
					return;
				}
				var id = entry.target.getAttribute('id');
				if (!id) {
					return;
				}
				links.forEach(function (link) {
					var href = link.getAttribute('href');
					link.classList.toggle('is-active', href === '#' + id);
				});
			});
		}, { rootMargin: '-45% 0px -45% 0px', threshold: 0 });

		sections.forEach(function (section) {
			if (section.id) {
				navObserver.observe(section);
			}
		});
	}
}());
</script>

<?php
get_footer();
